arguments.command:
python3 -c "
import parse

# Test R3 - sign specifiers
try:
    r = parse.extract_format('+d', set())
    print('R3 +d:', r)
except Exception as e:
    print('R3 +d error:', e)

try:
    r = parse.extract_format('-d', set())
    print('R3 -d:', r)
except Exception as e:
    print('R3 -d error:', e)

# Test R8 - hyphen in field name  
try:
    r = parse.parse('{my-field}', 'hello')
    print('R8 hyphen field:', r)
except Exception as e:
    print('R8 hyphen field error:', type(e).__name__, e)

# Test R9 - grouping chars in numbers
try:
    r = parse.parse('{:n}', '1,000')
    print('R9 comma grouping:', r)
except Exception as e:
    print('R9 comma grouping error:', type(e).__name__, e)

try:
    r = parse.parse('{:n}', '1_000')
    print('R9 underscore grouping:', r)
except Exception as e:
    print('R9 underscore grouping error:', type(e).__name__, e)
"
